/**
 * Irregular verbs bank.
 *
 * Each entry carries the 5 inflected forms (base, past simple, past
 * participle, gerund, third-person -s), a French gloss, level, and 10
 * fill-in-the-blank drills that exercise all 5 forms in context.
 *
 * Why drills per verb instead of a generic "irregular verb quiz":
 *   Knowing wrote ≠ written ≠ writing in isolation is one thing; knowing
 *   when each fits a sentence is another. The drills force the user to
 *   pick the right form for the context — not just recite paradigms.
 *
 * v1 ships ~10 high-frequency verbs. The catalogue is designed to grow
 * — adding a verb is a self-contained edit, no schema change needed.
 */

import type { Level } from '@/types'

export interface ConjugationDrill {
  /** Sentence with `___` for the blank. The base verb appears in parens
   *  in the prompt so the user knows which verb to conjugate. */
  prompt: string
  promptFr?: string
  /** Canonical answer (case-insensitive). */
  answer: string
  /** Other accepted spellings/contractions/synonyms. */
  acceptedAnswers?: string[]
  /** Why this form fits — shown after submit. */
  explanation: string
  explanationFr?: string
}

export interface ExampleForForm {
  /** Which of the 5 forms this example illustrates. */
  form: 'base' | 'past' | 'pastParticiple' | 'gerund' | 'thirdPerson'
  sentence: string
  sentenceFr?: string
}

export interface IrregularVerb {
  id: string
  base: string
  past: string
  pastParticiple: string
  gerund: string
  thirdPerson: string
  /** French translation of the base form. */
  meaningFr: string
  level: Level
  /** Optional brief note shown on the read panel. */
  note?: string
  noteFr?: string
  examples: ExampleForForm[]
  drills: ConjugationDrill[]
}

export const FORM_LABELS: Record<ExampleForForm['form'], { en: string; fr: string }> = {
  base: { en: 'Base form', fr: 'Forme de base' },
  past: { en: 'Past simple', fr: 'Prétérit (passé simple)' },
  pastParticiple: { en: 'Past participle', fr: 'Participe passé' },
  gerund: { en: 'Gerund / -ing', fr: 'Gérondif (-ing)' },
  thirdPerson: { en: '3rd person -s', fr: '3ᵉ personne du singulier' },
}

